function DrawText (Text: string, Speaker: string) {
    TempVariable = [
    mySprite.vy,
    mySprite.ay,
    mySprite.fx,
    mySprite.vx
    ]
    TextWriting = true
    mySprite.vy = 0
    mySprite.ay = 0
    mySprite.fx = 0
    mySprite.vx = 0
    Textbox2(scene.cameraProperty(CameraProperty.Left), scene.cameraProperty(CameraProperty.Top), 160, 40, assets.image`myImage12`)
    myTextSprite = fancyText.create(Speaker, 160, 1, fancyText.geometric_serif_6)
    myTextSprite.left = scene.cameraProperty(CameraProperty.Left) + 8
    myTextSprite.top = scene.cameraProperty(CameraProperty.Top) + 40
    myTextSprite.z = 21
    myTextSprite2 = fancyText.create(Text, 144, 1, customFont.MediumBlock_5b)
    myTextSprite2.left = scene.cameraProperty(CameraProperty.Left) + 8
    myTextSprite2.top = scene.cameraProperty(CameraProperty.Top) + 8
    myTextSprite2.z = 21
    fancyText.setAnimationSound(myTextSprite2, music.createSoundEffect(WaveShape.Noise, 261, 261, 255, 200, 20, SoundExpressionEffect.None, InterpolationCurve.Linear))
    fancyText.animateAtSpeed(myTextSprite2, fancyText.TextSpeed.Fast, fancyText.AnimationPlayMode.UntilDone)
    pauseUntil(() => !(controller.A.isPressed()))
    pauseUntil(() => controller.A.isPressed())
    sprites.destroy(myTextSprite)
    sprites.destroy(myTextSprite2)
    sprites.destroy(TextboxSprite)
    TextWriting = false
    mySprite.vy = TempVariable[0]
    mySprite.ay = TempVariable[1]
    mySprite.fx = TempVariable[2]
    mySprite.vx = TempVariable[3]
}
