function Music (ID: number) {
    music.stopAllSounds()
    CurrentlyPlaying = ID
    if (ID == 0) {
        music.play(music.createSong(assets.song`title screen`), music.PlaybackMode.LoopingInBackground)
    } else if (ID == 1) {
        music.play(music.createSong(assets.song`town1`), music.PlaybackMode.LoopingInBackground)
    } else if (ID == 2) {
        music.play(music.createSong(assets.song`mySong0`), music.PlaybackMode.LoopingInBackground)
    } else if (ID == 3) {
        music.play(music.createSong(assets.song`mySong9`), music.PlaybackMode.LoopingInBackground)
    } else {
    	
    }
}
function Doors (ID: number) {
    Rooms = [tileUtil.createSmallMap(tilemap`level34`), tileUtil.createSmallMap(tilemap`level56`)]
    tiles.setCurrentTilemap(tileUtil.cloneMap(Rooms[ID]))
    if (ID == 0) {
        tiles.placeOnTile(mySprite, tiles.getTileLocation(3, 10))
    } else if (ID == 1) {
        tiles.placeOnTile(mySprite, tiles.getTileLocation(3, 10))
        Shopkeeper = sprites.create(assets.image`myImage14`, SpriteKind.Shop)
        tiles.placeOnTile(Shopkeeper, tiles.getTileLocation(11, 9))
        Shopkeeper.bottom = 88
        Shopkeeper.z = mySprite.z - 1
    }
}
