function Array_of_all_Tile_in_Tilemap (Tile: Image, TIlemap: tiles.TileMapData[]) {
    TempList = []
    tileUtil.forEachTileInMap(TIlemap[0], function (column, row, location) {
        if (tileUtil.tileIs(TIlemap[0], location, Tile)) {
            TempList.push(location)
        }
    })
    return TempList
}
